CREATE TABLE IF NOT EXISTS attendance (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), school_id UUID REFERENCES schools(id), student_id UUID REFERENCES profiles(id), subject_id UUID REFERENCES subjects(id) ON DELETE CASCADE, class TEXT NOT NULL, date DATE NOT NULL, status TEXT NOT NULL DEFAULT 'present', remarks TEXT, marked_by UUID REFERENCES profiles(id), created_at TIMESTAMPTZ DEFAULT NOW(), UNIQUE(student_id, date)); 
